class OrderedDict:
    def __init__(self):
        self._store = []

    def __setitem__(self, key, value):
        if key in self:
            self._store.remove((key, self[key]))
        self._store.append((key, value))

    def __getitem__(self, key):
        for k, v in self._store:
            if k == key:
                return v
        raise KeyError(key)

    def __contains__(self, key):
        for k, _ in self._store:
            if k == key:
                return True
        return False

    def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        if not self._store:
            raise KeyError('popitem(): dictionary is empty')
        return self._store.pop(0)

