class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        root_inventory = self.load_inventory(version_dirs[0])
        content_digests = self.collect_content_digests(root_inventory)

        for version_dir in version_dirs[1:]:
            inventory = self.load_inventory(version_dir)
            self.validate_inventory(inventory, content_digests)
            content_digests.update(self.collect_content_digests(inventory))

    def load_inventory(self, version_dir):
        inventory_path = os.path.join(version_dir, 'inventory.txt')
        with open(inventory_path, 'r') as f:
            return {line.strip().split()[0]: line.strip().split()[1] for line in f}

    def collect_content_digests(self, inventory):
        content_digests = {}
        for path, digest in inventory.items():
            content_digests[path] = digest
        return content_digests

    def validate_inventory(self, inventory, content_digests):
        for path, digest in inventory.items():
            if path in content_digests and content_digests[path] != digest:
                raise ValueError(f"Digest mismatch for {path}: expected {content_digests[path]}, got {digest}")

