            raise IRValidatorException(f"Error parsing YAML content: {e}")

        schema = {
            "type": "object",
            "required": ["required_field1", "required_field2"],
            "properties": {
                "required_field1": {"type": "string"},
                "required_field2": {"type": "integer"}
            }
        }

        try:
